const gridWidth=64,gridHeight=40,sampleCount=gridWidth*gridHeight,cellColumns=gridWidth-1,cellRows=gridHeight-1,cellCount=cellColumns*cellRows,logicalWidth=360,logicalHeight=216,seed=42,randomDraws=255,noiseOctaves=2,noiseWeights=[.68,.32],noiseDomains=[{xScale:3.2,xOffset:7.25,yScale:2.4,yOffset:11.5,zScale:1,zOffset:3.75},{xScale:6.4,xOffset:19.5,yScale:4.8,yOffset:5.75,zScale:2,zOffset:13.25}],zDrift=.0015,levels=[.24,.33,.42,.51,.60,.69,.78],majorIndices=[2,5],indexLevelIndex=3,indexLevel=levels[indexLevelIndex],maxDelta=50;
const ambiguityScale=64,ambiguityTieRule='Q>=-epsilon:T-R+B-L;Q<-epsilon:T-L+R-B',edgeDirections={T:'TL-to-TR',R:'TR-to-BR',B:'BL-to-BR',L:'TL-to-BL'},casePairs=[[],[['T','L']],[['T','R']],[['L','R']],[['R','B']],null,[['T','B']],[['L','B']],[['B','L']],[['T','B']],null,[['R','B']],[['L','R']],[['T','R']],[['T','L']],[]];
function clamp(value,minimum,maximum){return Math.max(minimum,Math.min(maximum,value))}
function normalizeZero(value){return Object.is(value,-0)?0:value}
function lerp(first,second,amount){return first+(second-first)*amount}
function edgePoint(edge,column,row,level,tl,tr,br,bl){let s0,s1,x0,y0,x1,y1;if(edge==='T'){s0=tl-level;s1=tr-level;x0=column;y0=row;x1=column+1;y1=row}else if(edge==='R'){s0=tr-level;s1=br-level;x0=column+1;y0=row;x1=column+1;y1=row+1}else if(edge==='B'){s0=bl-level;s1=br-level;x0=column;y0=row+1;x1=column+1;y1=row+1}else{s0=tl-level;s1=bl-level;x0=column;y0=row;x1=column;y1=row+1}const denominator=s0-s1;let amount=Math.abs(denominator)<=1e-12?.5:s0/denominator;if(!Number.isFinite(amount))amount=.5;amount=clamp(amount,0,1);if(amount<=1e-12)amount=0;else if(amount>=1-1e-12)amount=1;const gx=normalizeZero(lerp(x0,x1,amount)),gy=normalizeZero(lerp(y0,y1,amount));return{x:normalizeZero(gx*logicalWidth/(gridWidth-1)),y:normalizeZero(gy*logicalHeight/(gridHeight-1)),t:amount,edge:edge}}
function ambiguityDecision(tl,tr,br,bl,level){const a=tl-level,b=tr-level,c=br-level,d=bl-level,q=a*c-b*d,epsilon=ambiguityScale*Number.EPSILON*Math.max(1,Math.abs(a*c),Math.abs(b*d)),positive=q>=-epsilon;return{q:q,epsilon:epsilon,branch:positive?'positive-or-tie':'negative',pairs:positive?[["T","R"],["B","L"]]:[["T","L"],["R","B"]]}}
function segmentKey(first,second){const a=first.x.toFixed(9)+','+first.y.toFixed(9),b=second.x.toFixed(9)+','+second.y.toFixed(9);return a<b?a+'|'+b:b+'|'+a}
function extractContours(field){const levelItems=[],allSegments=[],segmentCounts=[];let totalSegments=0,ambiguousCells=0,positiveBranches=0,negativeBranches=0,tieBranches=0,rejectedSegments=0,duplicateSegments=0;for(let levelIndex=0;levelIndex<levels.length;levelIndex++){const level=levels[levelIndex],segments=[],seen=new Set();for(let row=0;row<cellRows;row++)for(let column=0;column<cellColumns;column++){const cellIndex=row*cellColumns+column,tl=field.values[row*gridWidth+column],tr=field.values[row*gridWidth+column+1],br=field.values[(row+1)*gridWidth+column+1],bl=field.values[(row+1)*gridWidth+column],bits=(tl>=level?1:0)|(tr>=level?2:0)|(br>=level?4:0)|(bl>=level?8:0);let pairs=casePairs[bits],ambiguity=null;if(bits===5||bits===10){ambiguity=ambiguityDecision(tl,tr,br,bl,level);pairs=ambiguity.pairs;ambiguousCells++;if(ambiguity.branch==='negative')negativeBranches++;else{positiveBranches++;if(Math.abs(ambiguity.q)<=ambiguity.epsilon)tieBranches++}}for(let pairIndex=0;pairIndex<pairs.length;pairIndex++){const pair=pairs[pairIndex],first=edgePoint(pair[0],column,row,level,tl,tr,br,bl),second=edgePoint(pair[1],column,row,level,tl,tr,br,bl),dx=second.x-first.x,dy=second.y-first.y,lengthSquared=dx*dx+dy*dy,length=Math.sqrt(lengthSquared);if(!Number.isFinite(first.x)||!Number.isFinite(first.y)||!Number.isFinite(second.x)||!Number.isFinite(second.y)||!Number.isFinite(lengthSquared)||lengthSquared<=1e-18){rejectedSegments++;continue}const key=segmentKey(first,second);if(seen.has(key)){duplicateSegments++;continue}seen.add(key);const sourceIndex=segments.length,item={sourceIndex:sourceIndex,levelIndex:levelIndex,level:level,cellIndex:cellIndex,row:row,column:column,bits:bits,edges:pair[0]+'-'+pair[1],x0:first.x,y0:first.y,x1:second.x,y1:second.y,length:length,midX:(first.x+second.x)/2,midY:(first.y+second.y)/2,ambiguity:ambiguity?{q:ambiguity.q,epsilon:ambiguity.epsilon,branch:ambiguity.branch}:null};segments.push(item);allSegments.push(item)}}const style=levelIndex===indexLevelIndex?{role:'index',color:colors.acc,width:1.5}:majorIndices.indexOf(levelIndex)>=0?{role:'major',color:colors.txt2,width:1}:{role:'minor',color:colors.line1,width:1};segmentCounts.push(segments.length);totalSegments+=segments.length;levelItems.push({levelIndex:levelIndex,level:level,style:style,segmentCount:segments.length,segments:segments})}return{levels:levelItems,allSegments:allSegments,segmentCounts:segmentCounts,totalSegments:totalSegments,ambiguousCells:ambiguousCells,positiveBranches:positiveBranches,negativeBranches:negativeBranches,tieBranches:tieBranches,rejectedSegments:rejectedSegments,duplicateSegments:duplicateSegments}}
return extractContours({values:values});
